import { expect, test, type Page } from "@playwright/test";
import { readFileSync } from "node:fs";
import { join } from "node:path";

/** Explorer browser specs (§8.2) — /api/granules intercepted with the COMMITTED fixture
 *  (app-ui/tests-e2e/fixtures/granules-bbox.json, generated by tools/gen_explorer_fixture.py
 *  through the REAL engine enrichment code; labelled as fixtures). /api/health and /api/tile-at
 *  are also intercepted (offline engine otherwise). Assertions: axis renders, the N-of-M chip
 *  follows the filters, selection fills the detail panel (incl. the owner's test vector),
 *  truncated/degraded banners, List-view parity with the canvas, engine-offline state, and a
 *  5,000-bar pan timing measurement. */
const FIXTURE = JSON.parse(readFileSync(
  join(__dirname, "fixtures", "granules-bbox.json"), "utf8")) as {
  granules: { id: string; stack: string; ref_time: string | null; sec_time: string | null;
              start: string | null; baseline_days: number | null; product: string | null;
              track: number | null; frame: number | null; cycle_ref: number | null;
              cycle_sec: number | null; polarization: string | null;
              range_bandwidth_mhz: number | null; collection: string | null; crid: string | null;
              version: string | null; orbit_accuracy: { asf: string | null; filename: string | null };
              size_bytes: number | null; footprint: [number, number][] | null; flags: string[] }[];
  stacks: { key: string }[];
  n_total: number;
};

const TILE = {
  ok: true,
  tile: {
    id: "11SLT86", epsg: 32611, size_m: 10000,
    bbox_lonlat: [-118.45, 33.7, -118.05, 34.3],
    center_lonlat: [-118.25, 34.05],
    polygon_lonlat: [[-118.45, 33.7], [-118.05, 33.7], [-118.05, 34.3], [-118.45, 34.3], [-118.45, 33.7]],
  },
};

async function routeEngine(page: Page, overrides: Record<string, unknown> = {}) {
  await page.route("**/api/health**", (r) =>
    r.fulfill({ json: { ok: true, scans_enabled: false, earthdata_credentials: "present",
                        cache_write: { status: "disabled", reason: null } } }));
  await page.route("**/api/tile-at**", (r) => r.fulfill({ json: TILE }));
  await page.route("**/api/granules**", (r) => {
    const url = new URL(r.request().url());
    const body = { ...FIXTURE, ...overrides, granules: overrides.granules ?? FIXTURE.granules };
    void url;
    return r.fulfill({ json: body });
  });
}

test.describe("granule explorer (fixtures)", () => {
  test("axis + lanes render; N-of-M chip matches; the test vector fills the detail panel", async ({ page }) => {
    await routeEngine(page);
    await page.goto("/granules?west=-118.45&south=33.7&east=-118.05&north=34.3&level=GUNW,GCOV");
    await expect(page.getByText("17 granules")).toBeVisible();
    await expect(page.getByText("2 stacks")).toBeVisible();

    // canvas is present and painted (non-trivial size)
    const box = await page.locator('canvas[role="application"]').boundingBox();
    expect(box).not.toBeNull();
    expect(box!.width).toBeGreaterThan(300);

    // per-stack lane headers repeat in the canvas: select the first GUNW bar via the LIST view
    // (deterministic), then assert the detail panel's real fields for the owner's test vector
    await page.getByLabel("List view").check();
    const row = page.locator("tr", { hasText: "NISAR_L2_PR_GUNW_031_034_A_019_033_4000_SH" });
    await row.first().click();
    await expect(page.getByText("ASF: MOE; filename: N")).toBeVisible();
    await expect(page.getByText("NISAR_L2_GUNW_PROVISIONAL_V1")).toBeVisible();
    await expect(page.getByText("2026-09-20T13:08:23Z UTC")).toBeVisible();
    await expect(page.getByText("2026-10-14T13:08:23Z UTC")).toBeVisible();
    await expect(page.getByText("24 d", { exact: true })).toBeVisible();
    await expect(page.getByText("cycle 31")).toBeVisible();
    await expect(page.getByText("cycle 33")).toBeVisible();
    await expect(page.getByText("undecoded", { exact: false }).first()).toBeVisible(); // the raw orbit letter is flagged
    // footprint mini-map exists for the selected stack
    await expect(page.locator('[role="img"][aria-label*="footprint mini-map"]')).toBeVisible();
  });

  test("filters change the N-of-M chip client-side; List view stays in parity", async ({ page }) => {
    await routeEngine(page);
    await page.goto("/granules?west=-118.45&south=33.7&east=-118.05&north=34.3&level=GUNW,GCOV");
    await expect(page.getByText("17 granules")).toBeVisible();
    // direction filter -> descending only (D071, 6 granules)
    await page.getByLabel("direction").selectOption("D");
    await expect(page.getByText(/6 of 17 match/)).toBeVisible();
    // track filter on top -> D071 has track 71
    await page.getByLabel("track", { exact: false }).fill("71");
    await expect(page.getByText(/6 of 17 match/)).toBeVisible();
    // junk day-of-month shows an inline message and is NOT applied
    await page.getByLabel("day of month").fill("banana");
    await expect(page.getByText("day-of-month: use 1–31")).toBeVisible();
    await expect(page.getByText(/6 of 17 match/)).toBeVisible(); // unchanged
  });

  test("truncated and degraded banners render from the engine's own flags", async ({ page }) => {
    await routeEngine(page, { truncated: true, degraded: true, search_budget: 10 });
    await page.goto("/granules?west=-118.45&south=33.7&east=-118.05&north=34.3");
    await expect(page.getByText("result budget hit — this list is incomplete")).toBeVisible();
    await expect(page.getByText("served from stale cache")).toBeVisible();
  });

  test("engine offline: loud banner with the URL, search disabled, no crash", async ({ page }) => {
    await page.route("**/api/health**", (r) => r.abort());
    await page.goto("/granules?west=-118.45&south=33.7&east=-118.05&north=34.3");
    await expect(page.getByText(/the engine API is not reachable at/)).toBeVisible();
    await expect(page.getByRole("button", { name: /Search/ })).toBeDisabled();
  });

  test("429 shows the rate-limit banner", async ({ page }) => {
    await page.route("**/api/health**", (r) =>
      r.fulfill({ json: { ok: true, earthdata_credentials: "present" } }));
    await page.route("**/api/granules**", (r) =>
      r.fulfill({ status: 429, headers: { "Retry-After": "42" },
                  json: { ok: false, error: "granule search rate limit hit — the engine searches ASF live; retry after the window resets" } }));
    await page.goto("/granules");
    await page.getByLabel("West").fill("-118.45");
    await page.getByLabel("South").fill("33.7");
    await page.getByLabel("East").fill("-118.05");
    await page.getByLabel("North").fill("34.3");
    await page.getByRole("button", { name: /Search/ }).click();
    await expect(page.getByText(/rate limited by the engine/)).toBeVisible();
  });

  test("invalid box (west > east) shows the engine's antimeridian text inline, no query", async ({ page }) => {
    let queried = false;
    await page.route("**/api/health**", (r) => r.fulfill({ json: { ok: true } }));
    await page.route("**/api/granules**", (r) => { queried = true; return r.fulfill({ json: FIXTURE }); });
    await page.goto("/granules");
    await page.getByLabel("West").fill("-117.0");
    await page.getByLabel("East").fill("-118.05");
    await page.getByLabel("South").fill("33.7");
    await page.getByLabel("North").fill("34.3");
    await page.getByRole("button", { name: /Search/ }).click();
    await expect(page.getByText(/box crosses the antimeridian/)).toBeVisible();
    expect(queried).toBe(false);
  });

  test("5,000-bar fixture pans at interactive rate (timing reported, not just asserted)", async ({ page }) => {
    // synthesize 5,000 GCOV bars deterministically (labelled synthetic ids) in the SAME shape
    const N = 5000;
    const granules = Array.from({ length: N }, (_, i) => {
      const day = 150 + Math.floor(i / 40);         // ~125 stacks over the window
      const track = 1 + (i % 40);
      const t = new Date(Date.UTC(2026, 5, 1) + day * 86_400_000);
      const id = `NISAR_L2_PR_GCOV_SYNTH_${String(i).padStart(5, "0")}`;
      return {
        id, product: "GCOV", stack: `${track % 2 ? "A" : "D"}${String(track).padStart(3, "0")}`,
        direction: track % 2 ? "A" : "D", track, frame: 19,
        start: t.toISOString().slice(0, 19) + "Z", stop: t.toISOString().slice(0, 19) + "Z",
        ref_time: null, sec_time: null, baseline_days: null, cycle_ref: null, cycle_sec: null,
        polarization: "HH", range_bandwidth_mhz: 40, collection: null, crid: null, version: "001",
        orbit_accuracy: { asf: null, filename: null }, size_bytes: null, footprint: null, flags: [],
      };
    });
    await routeEngine(page, { granules, n_total: N, stacks: [] });
    await page.goto("/granules?west=-118.45&south=33.7&east=-118.05&north=34.3");
    await expect(page.getByText(`${N} granules`)).toBeVisible();
    const canvas = page.locator('canvas[role="application"]');
    const box = await canvas.boundingBox();
    expect(box).not.toBeNull();
    // drag-pan several times and sample frame timing via rAF deltas
    const timing = await page.evaluate(async () => {
      const el = document.querySelector('canvas[role="application"]') as HTMLCanvasElement;
      const deltas: number[] = [];
      let last = performance.now();
      let running = true;
      const loop = (now: number) => {
        deltas.push(now - last);
        last = now;
        if (running) requestAnimationFrame(loop);
      };
      requestAnimationFrame(loop);
      const fire = (type: string, x: number, y: number) =>
        el.dispatchEvent(new PointerEvent(type, { bubbles: true, clientX: x, clientY: y, pointerId: 7 }));
      fire("pointerdown", 400, 200);
      for (let i = 0; i < 30; i++) {
        fire("pointermove", 400 + i * 8, 200);
        await new Promise((r) => setTimeout(r, 8));
      }
      fire("pointerup", 640, 200);
      running = false;
      deltas.shift();
      const avg = deltas.reduce((a, b) => a + b, 0) / deltas.length;
      const sorted = [...deltas].sort((a, b) => a - b);
      return { frames: deltas.length, avg, p95: sorted[Math.floor(sorted.length * 0.95)] };
    });
    console.log("5,000-bar pan timing:", JSON.stringify(timing));
    expect(timing.avg).toBeLessThan(34); // interactive (≥ ~30 fps average)
    expect(timing.frames).toBeGreaterThan(10);
  });
});
